//! Regression vectors generated by compiling the BBTools Java AVLL implementation.
//! These test both packed-state compatibility and the complete HLDLC pipeline.
use avloglog::AvLogLog;

fn splitmix(n: u64) -> u64 {
    let mut z = n.wrapping_add(0x9e37_79b9_7f4a_7c15);
    z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    z ^ (z >> 31)
}

#[test]
fn java_packed_state_and_hldlc_golden_vectors() {
    for line in include_str!("fixtures/java_reference.csv").lines() {
        if line.starts_with('#') {
            continue;
        }
        let columns: Vec<_> = line.split(',').collect();
        let registers = columns[1].parse::<usize>().unwrap();
        let count = columns[2].parse::<u64>().unwrap();
        let shift = columns[3].parse::<u32>().unwrap();
        let floor = columns[4].parse::<i32>().unwrap();
        let expected = columns[5].parse::<f64>().unwrap();
        let words: Vec<u64> = columns[6].split(':').map(|x| x.parse().unwrap()).collect();
        let mut actual = AvLogLog::new(registers).unwrap();
        if columns[0] == "merge" {
            let mut other = AvLogLog::new(registers).unwrap();
            for i in 0..count {
                if i % 2 == 0 {
                    actual.add_hash(splitmix(i));
                } else {
                    other.add_hash(splitmix(i));
                }
            }
            actual.add_sketch(&other).unwrap();
        } else {
            actual.add_hashes((0..count).map(|i| splitmix(i) >> shift));
        }
        assert_eq!(actual.global_nlz(), floor, "{line}");
        assert_eq!(actual.state(), words, "{line}");
        let error = (actual.estimate() - expected).abs();
        // Java's original pipeline has f32 constants and an f32 occupancy correction.
        // Allow a few ulps of those intermediates while requiring identical packed state.
        assert!(
            error <= 4e-7 * expected.max(1.0),
            "HLDLC mismatch: actual={}, Java={expected}, case={line}",
            actual.estimate()
        );
    }
}
